import {useState} from 'react';import api,{message} from '../services/api.js';
function download(rows,name){if(!rows.length)return;const keys=Object.keys(rows[0]);const csv=[keys.join(','),...rows.map(r=>keys.map(k=>JSON.stringify(typeof r[k]==='object'&&r[k]!==null?(r[k].name||r[k].title||''):r[k]??'')).join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`${name}.csv`;a.click();URL.revokeObjectURL(a.href)}
export default function Reports(){const [type,setType]=useState('summary'),[data,setData]=useState(null),[error,setError]=useState('');async function run(){try{setData((await api.get('/reports',{params:{type}})).data);setError('')}catch(e){setError(message(e))}}return <><div className="page-head"><div><h2>Reports</h2><p>Generate operational reports and export data.</p></div></div><div className="panel report-controls"><select value={type} onChange={e=>setType(e.target.value)}><option value="summary">Summary</option><option value="books">Books</option><option value="members">Members</option><option value="loans">Loans</option><option value="fines">Fines</option></select><button className="btn primary" onClick={run}>Generate report</button>{Array.isArray(data)&&<button className="btn" onClick={()=>download(data,type)}>Export CSV</button>}</div>{error&&<div className="alert error">{error}</div>}{data&&!Array.isArray(data)&&<div className="stats"><div className="stat"><div><span>Books</span><strong>{data.books}</strong></div></div><div className="stat"><div><span>Members</span><strong>{data.members}</strong></div></div><div className="stat"><div><span>Issued</span><strong>{data.issued}</strong></div></div><div className="stat"><div><span>Overdue</span><strong>{data.overdue}</strong></div></div></div>}{Array.isArray(data)&&<div className="panel table-wrap"><table><thead><tr>{Object.keys(data[0]||{}).filter(k=>!['_id','__v'].includes(k)).slice(0,7).map(k=><th key={k}>{k}</th>)}</tr></thead><tbody>{data.map((r,i)=><tr key={r._id||i}>{Object.keys(data[0]||{}).filter(k=>!['_id','__v'].includes(k)).slice(0,7).map(k=><td key={k}>{typeof r[k]==='object'&&r[k]!==null?(r[k].name||r[k].title||'—'):String(r[k]??'—')}</td>)}</tr>)}</tbody></table></div>}</>}
